<script setup>
import { computed,ref,watch } from 'vue'
import { api } from '../api'
import { CdcMessage } from './ui/feedback'
const props=defineProps({modelValue:Boolean,task:Object,sourceTableId:Number,defaultMode:String}),emit=defineEmits(['update:modelValue','submitted'])
const step=ref(0),mode=ref('LAST_SUCCESS'),table=ref(null),startAt=ref(''),batchId=ref(''),busy=ref(false),error=ref(''),plan=ref(null),confirmKafka=ref(false)
const options=computed(()=>(props.task?.targetSubscriptions||[]).flatMap(s=>s.tables.filter(t=>!props.sourceTableId||t.sourceTaskTableId===props.sourceTableId).map(t=>({value:t.id,label:`${s.name} · ${t.mapping.sourceTable} → ${[t.mapping.targetSchema,t.mapping.targetTable].filter(Boolean).join('.')}`}))))
const checkpointTables=ref([]),rangeError=ref('');let rangeRequest=0
const selectedRange=computed(()=>checkpointTables.value.find(t=>t.SUBSCRIPTION_TABLE_ID===table.value))
const date=v=>v?new Date(v).toLocaleString():'未知'
async function loadRanges(){const id=++rangeRequest;checkpointTables.value=[];rangeError.value='';try{const data=await api(`/tasks/${props.task.id}/checkpoints`);if(id===rangeRequest)checkpointTables.value=data.tables||[]}catch(e){if(id===rangeRequest)rangeError.value=e.message}}
const modes=[{id:'LAST_SUCCESS',title:'从上次成功投递后继续',description:'按顺序接管尚未成功的本地批次。'},{id:'FAILED_BATCH',title:'从失败批次继续',description:'选择当前目标表的失败批次 ID，重试并追平新增事件。'},{id:'TIME',title:'从本地指定时间回放',description:'仅使用仍保留且连续的本地批次，可能重复投递批次内更早的事件。'},{id:'FULL',title:'目标专属全量初始化',description:'重新扫描该源表，按主键覆盖目标后追平增量；不会清空目标。'}]
watch(()=>props.modelValue,open=>{if(open){loadRanges();step.value=0;error.value='';plan.value=null;confirmKafka.value=false;mode.value=props.defaultMode||'LAST_SUCCESS';table.value=options.value.length===1?options.value[0].value:null;startAt.value='';batchId.value=''}else{rangeRequest++}})
function offsetTime(value,zone){
  // Resolve the entered wall clock using the task time zone, including DST.
  const parts=value.split(/[-T:]/).map(Number),utc=Date.UTC(parts[0],parts[1]-1,parts[2],parts[3],parts[4]);let instant=utc
  const fmt=new Intl.DateTimeFormat('en-CA',{timeZone:zone||'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'})
  for(let i=0;i<3;i++){const p=Object.fromEntries(fmt.formatToParts(new Date(instant)).map(x=>[x.type,x.value]));const wall=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);instant+=utc-wall}
  const p=Object.fromEntries(fmt.formatToParts(new Date(instant)).map(x=>[x.type,x.value]));if(+p.hour!==parts[3]||+p.minute!==parts[4]||+p.day!==parts[2])throw new Error('该时间在任务时区不存在，请检查夏令时转换')
  return new Date(instant).toISOString()
}
async function precheck(){busy.value=true;error.value='';try{if(!table.value)throw new Error('请选择目标订阅及目标表');if(mode.value==='TIME'&&!startAt.value)throw new Error('请选择本地采集时间');const body={subscriptionTableId:table.value,mode:mode.value,batchId:batchId.value};if(mode.value==='TIME')body.startAt=offsetTime(startAt.value,props.task.timeZone);plan.value=await api(`/tasks/${props.task.id}/recoveries/precheck`,{method:'POST',body:JSON.stringify(body)});step.value=1}catch(e){error.value=e.message}finally{busy.value=false}}
async function submit(){busy.value=true;error.value='';try{await api(`/tasks/${props.task.id}/recoveries`,{method:'POST',body:JSON.stringify({planId:plan.value.planId,confirmKafkaDuplicates:confirmKafka.value})});emit('update:modelValue',false);emit('submitted');CdcMessage.success('恢复作业已受理，可在位点页查看进度')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><cdc-modal :model-value="modelValue" title="目标表重跑与时间回放" width="640px" @update:model-value="emit('update:modelValue',$event)"><cdc-steps :active="step"><cdc-step title="选择范围与起点"/><cdc-step title="预检与确认"/></cdc-steps><div v-if="error" class="alert-bar error" role="alert">{{error}}</div><template v-if="step===0"><div class="alert-bar">仅接管选中的目标表，共享采集、其他表与目标继续运行。</div><cdc-form-item label="目标订阅 / 表映射" required><cdc-select v-model="table"><cdc-option v-for="o in options" :key="o.value" :label="o.label" :value="o.value"/></cdc-select></cdc-form-item><label v-for="m in modes" :key="m.id" class="rerun-option" :class="{selected:mode===m.id}"><input v-model="mode" type="radio" name="recovery-mode" :value="m.id"/><div><div class="rerun-option-title">{{m.title}}</div><div class="rerun-option-desc">{{m.description}}</div></div></label><cdc-form-item v-if="mode==='TIME'" :label="'本地采集时间 · '+(task.timeZone||'Asia/Shanghai')"><input v-model="startAt" type="datetime-local"/><div v-if="selectedRange?.availableFrom" class="form-help">本地可用范围：{{date(selectedRange.availableFrom)}} 至 {{date(selectedRange.availableTo)}}（预检将再次校验文件连续性和完整性）</div><div v-else class="form-help">{{rangeError?'历史范围读取失败：'+rangeError:'该目标表尚无可验证的本地历史，请选择全量初始化或先执行预检确认。'}}</div><div class="form-help">使用任务时区。系统从覆盖此时间的完整批次起点开始，不修改源采集位点。</div></cdc-form-item><cdc-form-item v-if="mode==='FAILED_BATCH'" label="失败批次 ID"><cdc-input v-model="batchId"/></cdc-form-item></template><template v-else><div class="rerun-info"><div class="precheck-row"><span>源表</span><strong>{{plan.sourceTable}}</strong></div><div class="precheck-row"><span>目标表</span><strong>{{plan.targetTable}}</strong></div><div class="precheck-row"><span>实际起点（完整批次）</span><span>{{plan.actualStart||'重新扫描快照'}}</span></div><div v-if="mode==='TIME'" class="form-help">从覆盖所选时间的完整批次重投；实际起点至指定时间之间的事件可能重复投递。</div><div class="precheck-row"><span>已验证事件 / 文件字节</span><span>{{plan.events?.toLocaleString()}} / {{plan.bytes?.toLocaleString()}}</span></div><div class="precheck-row"><span>计划有效期</span><span>5 分钟，提交时再次校验</span></div></div><div class="alert-bar warning">{{plan.warning}}</div><cdc-checkbox v-if="plan.kafka" v-model="confirmKafka">我已了解并确认 Kafka 重复消息风险</cdc-checkbox></template><template #footer><cdc-button :disabled="busy" @click="step===1?step=0:emit('update:modelValue',false)">{{step===1?'上一步':'取消'}}</cdc-button><cdc-button v-if="step===0" type="primary" :loading="busy" @click="precheck">执行预检</cdc-button><cdc-button v-else type="primary" :loading="busy" :disabled="plan?.kafka&&!confirmKafka" @click="submit">确认提交恢复</cdc-button></template></cdc-modal></template>
